from pathlib import Path

html_path = Path('android/app/src/main/assets/web/admin.html')
html = html_path.read_text(encoding='utf-8')

card_anchor = '<h4>Rental di PC terpilih</h4>'
card = r'''<div class="card" id="shutdownTimerCard" style="margin:14px 0;border:1px solid #ef4444;background:rgba(127,29,29,.12)">
<div class="top"><div><h3 style="margin:0">⏱ Timer Shutdown PC</h3><div class="muted">Timer berjalan di PC Billing. Pratinjau tidak mengirim perintah. Shutdown diblokir jika sesi rental aktif/paused.</div></div><span class="pill">Owner only</span></div>
<div class="cards2"><div class="field"><label>Target PC</label><select id="shutdownTimerDevice" onchange="renderPcShutdownTimerStatus()" style="width:100%"><option value="">Memuat PC…</option></select></div><div class="field"><label>Durasi (jam)</label><input id="shutdownTimerHours" type="number" min="0" max="24" step="1" value="2" inputmode="numeric"></div><div class="field"><label>Durasi (menit)</label><input id="shutdownTimerMinutes" type="number" min="0" max="59" step="1" value="15" inputmode="numeric"></div></div>
<div class="row"><button type="button" onclick="previewPcShutdownTimer()">Pratinjau Pilihan</button><button type="button" id="shutdownTimerScheduleBtn" class="danger" onclick="schedulePcShutdownTimer()">Jadwalkan Shutdown</button><button type="button" id="shutdownTimerCancelBtn" onclick="cancelPcShutdownTimer()" disabled>Batalkan Timer</button><button type="button" onclick="refreshPcShutdownTimerStatus()">Refresh Status</button></div>
<div id="shutdownTimerStatus" class="msg" role="status" aria-live="polite" style="margin-top:10px;border-left-color:#f59e0b">Target: Galtys bila tersedia • Durasi awal: 2 jam 15 menit • Belum ada perintah yang dikirim.</div>
<div class="muted" style="margin-top:8px">PC offline = perintah tidak dikirim. Bila rental aktif/paused sebelum waktu habis, timer otomatis dibatalkan. Timer tidak menghentikan atau mengubah sesi rental.</div></div>
<h4>Rental di PC terpilih</h4>'''

if 'shutdownTimerCard' not in html:
    if html.count(card_anchor) != 1:
        raise SystemExit('Timer card insertion anchor is not unique; refusing to patch.')
    html = html.replace(card_anchor, card, 1)
    load_anchor = 'devicesCache=rows;renderRecoveryDeviceOptions();'
    if html.count(load_anchor) != 1:
        raise SystemExit('loadDevices insertion anchor is not unique; refusing to patch.')
    html = html.replace(load_anchor, load_anchor + 'renderShutdownTimerDeviceOptions(rows);', 1)
    render_anchor = 'await renderSelectedDevice();await loadAccountsForSelectedDevice()}'
    if html.count(render_anchor) != 1:
        raise SystemExit('loadDevices render end is not unique; refusing to patch.')
    html = html.replace(render_anchor, 'await renderSelectedDevice();await loadAccountsForSelectedDevice();renderPcShutdownTimerStatus()}', 1)

if 'function schedulePcShutdownTimer()' not in html:
    function_anchor = 'async function waitDeviceCommand(commandId,timeoutMs=12000)'
    if html.count(function_anchor) != 1:
        raise SystemExit('waitDeviceCommand insertion anchor is not unique; refusing to patch.')
    js = r'''const __aniShutdownTimerByDevice=window.__aniShutdownTimerByDevice||(window.__aniShutdownTimerByDevice={});
function shutdownTimerTarget(){const id=$('shutdownTimerDevice')?.value||'';return devicesCache.find(d=>d.id===id)||null;}
function renderShutdownTimerDeviceOptions(rows){const el=$('shutdownTimerDevice');if(!el)return;const old=el.value;el.innerHTML=(rows||[]).map(d=>'<option value="'+esc(d.id)+'">'+esc(d.device_name||'PC')+' • '+(d.uiStatus==='online'?'ONLINE':'OFFLINE')+'</option>').join('')||'<option value="">Belum ada PC</option>';const find=id=>(rows||[]).some(d=>d.id===id);const galtys=(rows||[]).find(d=>String(d.device_name||'').trim().toLowerCase()==='galtys'||String(d.client_id||'').trim().toLowerCase()==='galtys');el.value=find(old)?old:(galtys?.id||((rows||[]).find(d=>d.id===selectedDeviceId)?.id)||((rows||[]).find(d=>d.uiStatus==='online')?.id)||((rows||[])[0]?.id)||'');}
function getPcShutdownTimer(d){if(!d)return null;const local=__aniShutdownTimerByDevice[d.id]||null,remote=d.metadata?.shutdownTimer&&typeof d.metadata.shutdownTimer==='object'?d.metadata.shutdownTimer:null;if(!local)return remote;if(!remote)return local;return (Date.parse(local.updatedAt||0)||0)>=(Date.parse(remote.updatedAt||0)||0)?local:remote;}
function shutdownTimerDueMs(t){if(!t)return 0;const v=t.dueAt??t.due_at??0;if(typeof v==='number')return v>0&&v<1e12?v*1000:v;const n=Date.parse(String(v||''));return Number.isFinite(n)?n:0;}
function formatShutdownCountdown(ms){const n=Math.max(0,Math.ceil(ms/1000)),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
function shutdownTimerDuration(){const h=Number($('shutdownTimerHours')?.value),m=Number($('shutdownTimerMinutes')?.value),s=h*3600+m*60;if(!Number.isInteger(h)||h<0||h>24||!Number.isInteger(m)||m<0||m>59||s<60||s>86400)throw new Error('Durasi harus 1 menit sampai 24 jam.');return s;}
function shutdownTimerStateText(t){if(!t)return 'Belum ada timer shutdown aktif.';const s=String(t.status||'').toLowerCase(),due=shutdownTimerDueMs(t);if(s==='preview')return 'PRATINJAU SAJA • '+(t.deviceName||'PC')+' • Durasi '+formatShutdownCountdown(Number(t.durationSeconds||0)*1000)+' • Perkiraan '+(due?new Date(due).toLocaleString('id-ID'):'-')+'. Tidak ada perintah dikirim.';if(s==='queued')return 'Permintaan timer masuk antrean, belum dikonfirmasi PC.';if(s==='scheduled')return 'TIMER AKTIF • Sisa '+formatShutdownCountdown(due-Date.now())+' • Target '+new Date(due).toLocaleString('id-ID')+'.';if(s==='blocked_active_session')return 'SHUTDOWN DIBLOKIR • Sesi rental aktif/paused terdeteksi. Timer dibatalkan otomatis.';if(s==='cancelled'||s==='none')return 'Timer shutdown sudah tidak aktif.';if(s==='failed')return 'Timer gagal: '+String(t.reason||t.message||'periksa PC Billing.');if(s==='executing')return 'Waktu timer tercapai; periksa status PC untuk konfirmasi.';return 'Status timer: '+s+'.';}
function renderPcShutdownTimerStatus(){const box=$('shutdownTimerStatus'),d=shutdownTimerTarget();if(!box)return;const t=getPcShutdownTimer(d),s=String(t?.status||'').toLowerCase();box.textContent=(d?'PC '+(d.device_name||d.client_id||'target')+' • ':'')+shutdownTimerStateText(t);box.style.borderLeftColor=s==='blocked_active_session'||s==='failed'?'#ef4444':s==='scheduled'?'#f59e0b':'#64748b';const owner=ctx?.role==='owner',online=d?.uiStatus==='online';const set=$('shutdownTimerScheduleBtn'),cancel=$('shutdownTimerCancelBtn');if(set)set.disabled=!owner||!online||s==='scheduled';if(cancel)cancel.disabled=!owner||!online||s!=='scheduled';}
function previewPcShutdownTimer(){try{const d=shutdownTimerTarget();if(!d)throw new Error('Pilih PC target.');const seconds=shutdownTimerDuration();__aniShutdownTimerByDevice[d.id]={status:'preview',deviceName:d.device_name||d.client_id,durationSeconds:seconds,dueAt:Date.now()+seconds*1000,updatedAt:new Date().toISOString()};renderPcShutdownTimerStatus();msg('Pratinjau saja. Tidak ada perintah shutdown atau timer yang dikirim ke PC.');}catch(e){msg(e.message||'Pilihan timer tidak valid.',true);}}
async function schedulePcShutdownTimer(){const d=shutdownTimerTarget();try{if(ctx?.role!=='owner')throw new Error('Hanya Owner/Super Admin dapat menjadwalkan shutdown.');if(!currentOrg||!d)throw new Error('Pilih workspace dan PC.');if(d.uiStatus!=='online')throw new Error('PC offline. Perintah tidak dikirim.');if(d.metadata?.activeCode||d.metadata?.pausedCode)throw new Error('Shutdown diblokir: ada sesi rental aktif/paused.');const seconds=shutdownTimerDuration(),due=Date.now()+seconds*1000;const text='Jadwalkan shutdown untuk '+(d.device_name||d.client_id)+'?\\n\\nDurasi: '+formatShutdownCountdown(seconds*1000)+'\\nPerkiraan: '+new Date(due).toLocaleString('id-ID')+'\\n\\nIni hanya menjadwalkan timer; tidak mematikan PC sekarang. Jika sesi rental aktif/paused, PC akan membatalkan timer. Lanjutkan?';if(!confirm(text))return;const r=await rpc('admin_command',{p_org_id:currentOrg.id,p_device_id:d.id,p_command:'shutdown_timer_set',p_payload:{seconds,source:'admin-android'}});if(r?.ok===false)throw new Error(r.message||r.error||'Backend menolak perintah.');const id=r?.command_id||r?.id;if(!id)throw new Error('Command ID tidak diterima.');__aniShutdownTimerByDevice[d.id]={status:'queued',deviceName:d.device_name||d.client_id,updatedAt:new Date().toISOString()};renderPcShutdownTimerStatus();const a=await waitDeviceCommand(id,20000);if(a?.status==='failed')throw new Error(a.result?.message||a.result?.error||'PC menolak timer.');if(a?.status!=='completed'){msg('Perintah masih antre. Status timer belum terkonfirmasi; jangan mengandalkannya sebelum refresh.',true);return;}const t=a.result?.timer||{status:'scheduled',durationSeconds:seconds,dueAt:due,updatedAt:new Date().toISOString()};__aniShutdownTimerByDevice[d.id]={...t,deviceName:d.device_name||d.client_id,updatedAt:new Date().toISOString()};renderPcShutdownTimerStatus();msg('Timer shutdown diterima PC. Tidak ada shutdown langsung sekarang.');}catch(e){const m=String(e?.message||e||'Error');msg(/COMMAND_NOT_ALLOWED|INVALID_COMMAND|device_commands_command_check/i.test(m)?'Backend belum mengizinkan timer. Periksa docs/PC-SHUTDOWN-TIMER-MIGRATION.sql. Detail: '+m:'Gagal menjadwalkan timer: '+m,true);if(d&&__aniShutdownTimerByDevice[d.id]?.status==='queued')__aniShutdownTimerByDevice[d.id]={status:'failed',reason:m,updatedAt:new Date().toISOString()};renderPcShutdownTimerStatus();}}
async function cancelPcShutdownTimer(){const d=shutdownTimerTarget();try{if(ctx?.role!=='owner')throw new Error('Hanya Owner/Super Admin dapat membatalkan timer.');if(!currentOrg||!d)throw new Error('Pilih workspace dan PC.');if(d.uiStatus!=='online')throw new Error('PC offline; pembatalan tidak dapat dikirim.');if(String(getPcShutdownTimer(d)?.status||'')!=='scheduled')throw new Error('Tidak ada timer aktif terkonfirmasi.');if(!confirm('Batalkan timer shutdown '+(d.device_name||d.client_id)+'?'))return;const r=await rpc('admin_command',{p_org_id:currentOrg.id,p_device_id:d.id,p_command:'shutdown_timer_cancel',p_payload:{source:'admin-android'}});if(r?.ok===false)throw new Error(r.message||r.error||'Server menolak pembatalan.');const id=r?.command_id||r?.id;if(!id)throw new Error('Command ID tidak diterima.');const a=await waitDeviceCommand(id,20000);if(a?.status==='failed')throw new Error(a.result?.message||a.result?.error||'PC menolak pembatalan.');if(a?.status!=='completed')throw new Error('Pembatalan belum dikonfirmasi PC; refresh status.');__aniShutdownTimerByDevice[d.id]={...(a.result?.timer||{}),status:'cancelled',deviceName:d.device_name||d.client_id,updatedAt:new Date().toISOString()};renderPcShutdownTimerStatus();msg('Timer shutdown berhasil dibatalkan oleh PC.');}catch(e){msg('Gagal membatalkan timer: '+String(e?.message||e),true);renderPcShutdownTimerStatus();}}
async function refreshPcShutdownTimerStatus(){const d=shutdownTimerTarget();try{if(ctx?.role!=='owner')throw new Error('Hanya Owner/Super Admin dapat membaca status timer.');if(!currentOrg||!d)throw new Error('Pilih workspace dan PC.');if(d.uiStatus!=='online')throw new Error('PC offline.');const r=await rpc('admin_command',{p_org_id:currentOrg.id,p_device_id:d.id,p_command:'shutdown_timer_status',p_payload:{source:'admin-android'}});if(r?.ok===false)throw new Error(r.message||r.error||'Server menolak status.');const id=r?.command_id||r?.id;if(!id)throw new Error('Command ID tidak diterima.');const a=await waitDeviceCommand(id,15000);if(a?.status==='failed')throw new Error(a.result?.message||a.result?.error||'PC gagal membaca status timer.');if(a?.status!=='completed')throw new Error('Status belum dikonfirmasi PC.');__aniShutdownTimerByDevice[d.id]={...(a.result?.timer||{status:'none'}),deviceName:d.device_name||d.client_id,updatedAt:new Date().toISOString()};renderPcShutdownTimerStatus();}catch(e){msg('Gagal refresh status timer: '+String(e?.message||e),true);renderPcShutdownTimerStatus();}}
if(!window.__aniShutdownTimerUiTick){window.__aniShutdownTimerUiTick=true;window.setInterval(renderPcShutdownTimerStatus,1000);}
'''
    html = html.replace(function_anchor, js + function_anchor, 1)

gradle_path = Path('android/app/build.gradle')
gradle = gradle_path.read_text(encoding='utf-8')
if "versionCode 40" not in gradle or "versionName '12.1.12'" not in gradle:
    if "versionCode 41" not in gradle or "versionName '12.1.13'" not in gradle:
        raise SystemExit('Unexpected Android baseline; expected 12.1.12/code40 or patched 12.1.13/code41.')
    else:
        pass
else:
    gradle = gradle.replace('versionCode 40','versionCode 41',1).replace("versionName '12.1.12'","versionName '12.1.13'",1)
    gradle_path.write_text(gradle,encoding='utf-8')
Path('VERSION.txt').write_text('v12.1.13-pc-shutdown-timer\n',encoding='utf-8')
html_path.write_text(html, encoding='utf-8')
print('Patched Admin shutdown timer UI; preview, confirmation, cancel/status and safety guards; version 12.1.13.')
